    "definition": "O In-the-Hoop (ITH / Bordado Construtivo no Bastidor / Peça Feita no Bastidor) é a técnica e metodologia avançada de digitalização e manufatura têxtil na qual um artefato tridimensional acabado — como nécessaires com zíper embutido, porta-moedas, chaveiros tipo almofadinha, bichinhos de pelúcia, máscaras de dormir, carteiras forradas e tags de bagagem — é inteiramente estruturado, quiltado, decorado, forrado e montado por meio de etapas sequenciais automatizadas executadas diretamente sobre o bastidor da máquina de bordar computadorizada, dispensando ou minimizando o uso de máquinas de costura convencionais.",
    "technicalDetails": "Arquitetura da matriz ITH:\n• Camada 1 (Placement Line): Ponto corrido simples que desenha no estabilizador onde o tecido principal deve ser colocado;\n• Camada 2 (Tackdown Line): Ponto corrido ou zigue-zague que prende o tecido e a manta estruturadora;\n• Camadas Intermediárias: Bordado decorativo, pontos cheios, apliques e quiltings;\n• Camada de Acessórios: Paradas programadas (Stop Code) para aplicação de zíperes, alças de fita e passadores de metal;\n• Camada de Fechamento (Seaming Line): Ponto corrido triplo reforçado (Bean Stitch) a 2,5mm da borda que une frente, verso e forro pelo avesso deixando uma abertura de desviramento de 3cm a 5cm.",
